def build():
    result = {}
    for h in HEROES:
        hid, name, display_name, role, attr, aliases, tags, counters, countered_by = h
        # Add basic name variants to aliases
        full_aliases = list(set([display_name.lower(), name.replace('npc_dota_hero_', '')] + aliases))
        result[str(hid)] = {
            "name": name,
            "display_name": display_name,
            "role": role,
            "attr": attr,
            "aliases": full_aliases,
            "tags": tags,
            "counters": counters,
            "countered_by": countered_by
        }
    
    out_path = Path('/home/aruchimo/projects/dota2-aegis-plus/data/heroes.json')
    with open(out_path, 'w', encoding='utf-8') as f:
        json.dump(result, f, ensure_ascii=False, indent=2)

    print(f"Successfully generated heroes.json with {len(result)} heroes!")

if __name__ == '__main__':
    build()
